script:
# Machine-wide DLL load hooks (AppInit_DLLs + AppCertDLLs) pointed at a benign placeholder file.
$dll = if ($DLL_PATH) { $DLL_PATH } else { 'C:\Windows\System32\inproc_helper.dll' }
if (-not (Test-Path $dll)) {
  Set-Content -Path $dll -Value 'training marker: placeholder for a user-mode hook library (not a PE)' -Encoding ascii
}
$win = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows'
Set-ItemProperty -Path $win -Name 'AppInit_DLLs' -Value $dll -Type String -Force
Set-ItemProperty -Path $win -Name 'LoadAppInit_DLLs' -Value 1 -Type DWord -Force
Set-ItemProperty -Path $win -Name 'RequireSignedHooks' -Value 0 -Type DWord -Force
$certs = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\AppCertDLLs'
if (-not (Test-Path $certs)) { New-Item -Path $certs -Force | Out-Null }
Set-ItemProperty -Path $certs -Name 'inproc_helper' -Value $dll -Type String -Force
